  PRIMARY KEY (`INKIND_TRANS_ID`),
  KEY `FK_InKindTrans_Ledger` (`LEDGER_ID`),
  KEY `FK_InKindTrans_Project` (`PROJECT_ID`),
  CONSTRAINT `FK_PROJECT_ID` FOREIGN KEY (`PROJECT_ID`) REFERENCES `master_project` (`PROJECT_ID`)
